interface.definition:
a!localVariables(
  local!gettaskdetails: if(
    a!isNullOrEmpty(ri!nomination),
    null(),
    #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3066463"(
      requestId: ri!nomination.nominationId,
      moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164394",
      isCompleted: true,
      returnCDT: true
    ),

  ),
  {
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: {
        #"SYSTEM_SYSRULES_sectionLayout_v1"(
          label: "",
          contents: {
            /*a!cardLayout(*/
              /*marginBelow: "MORE",*/
              /*contents: {*/
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  value: #"SYSTEM_SYSRULES_richTextItem_v1"(
                    text: "Are you sure you want to mark this nomination as completed ?",
                    style: "PLAIN",
                    size: "MEDIUM",

                  )
                ),
              /*},*/
              /*height: "AUTO",*/
              /*style: "TRANSPARENT",*/
/*              */
            /*),*/
            #"SYSTEM_SYSRULES_ButtonLayout"(
              primaryButtons: #"SYSTEM_SYSRULES_buttonWidget_v1"(
                label: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3155707",
                value: true(),
                saveInto: {
                  ri!save,
                  a!save(
                    ri!nomination,
                    #"urn:appian:function:v1:a:update"(
                      ri!nomination,
                      "statusId",
                      #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5076350"
                    )
                  ),
                  a!save(
                    ri!auditHistory,
                    'type!{urn:com:appian:types:CAW}CAW_Audit'(
                      taskId: local!gettaskdetails.taskId,
                      requestId: ri!nomination.nominationId,
                      version: 1,
                      moduleTypeId: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3164394",
                      statusId: local!gettaskdetails.statusId,
                      /*action: rule!CAW_CalculateCompleteNominationSubmitAudit(currentStatusID: ri!nomination.statusId),*/
                      action: "Marked as Complete",
                      createdBy: loggedInUser(),
                      createdOn: now()
                    )
                  ),

                },
                submit: true()
              ),
              secondaryButtons: #"SYSTEM_SYSRULES_buttonWidget_v1"(
                label: "Cancel",
                value: false(),
                saveInto: ri!save,
                submit: true(),

              ),

            )
          }
        )
      },
      height: "AUTO",
      style: "TRANSPARENT",
      marginBelow: "STANDARD"
    )
  }
)
